import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Skills & Skillcap","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/characters/skills-and-skillcap.md","filePath":"game-design/characters/skills-and-skillcap.md"}'),r={name:"game-design/characters/skills-and-skillcap.md"};function s(o,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="skills-skillcap" tabindex="-1">Skills &amp; Skillcap <a class="header-anchor" href="#skills-skillcap" aria-label="Permalink to &quot;Skills &amp; Skillcap&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; open questions remain Unresolved. Referenced Accepted decisions retain their existing scope. <strong>Implementation/availability:</strong> no changes to gameplay or runtime configuration; this redesign is not established as live. <strong>Verification:</strong> documentation review, not a playtest; current availability is not established here. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/guide/characters/skills.html">Player-facing overview</a> · <a href="/Syrolands-Public/game-design/characters/progression.html">Character progression</a></p><h2 id="cap-and-normal-maximum" tabindex="-1">Cap and normal maximum <a class="header-anchor" href="#cap-and-normal-maximum" aria-label="Permalink to &quot;Cap and normal maximum&quot;">​</a></h2><p>The direction is <strong>approximately 700 total skill points</strong>, <strong>100 normal maximum per skill</strong>, and <strong>no ordinary 120 progression planned</strong>. These are Proposed design targets, not confirmed runtime settings or removal of inherited 120 support. Mastery at 100 is not the beginning of all endgame; <a href="/Syrolands-Public/game-design/characters/progression.html#mastery-and-multiple-endgames">long-term aspirations</a> extend through knowledge and participation.</p><h2 id="desired-skill-gain" tabindex="-1">Desired skill gain <a class="header-anchor" href="#desired-skill-gain" aria-label="Permalink to &quot;Desired skill gain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Range</th><th>Proposed pace</th><th>Interpretation</th></tr></thead><tbody><tr><td>0–40</td><td>Very fast</td><td>Reach useful early capability quickly</td></tr><tr><td>40–60</td><td>Fast</td><td>Build-relevant competence, potentially during the first day</td></tr><tr><td>60–80</td><td>Normal</td><td>Substantial normal progression</td></tr><tr><td>80–90</td><td>Very slow</td><td>Expertise</td></tr><tr><td>90–100</td><td>Extremely slow</td><td>Significant mastery</td></tr></tbody></table><p>Relevant skills might reach roughly 40–60 in the first day depending on activity and build. This is an aspiration, not a guarantee for every skill or a fixed time budget. Exact hours, gain probabilities, attempt frequency and anti-macro/diminishing-return mechanics are balance/playtest work.</p><p><strong>Batch reconciliation:</strong> Batch 01 described 80–90 as “Slow”; Batch 02 describes it as “Very slow.” This page records the latest supplied proposal. The earlier source remains unchanged, and the profession page now links here. This is not promotion to Accepted balance or implementation.</p><h2 id="meaningful-capability-bands" tabindex="-1">Meaningful capability bands <a class="header-anchor" href="#meaningful-capability-bands" aria-label="Permalink to &quot;Meaningful capability bands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approximate band</th><th>Capability philosophy</th></tr></thead><tbody><tr><td>0</td><td>No meaningful discipline knowledge unless a background/starting competency grants fundamentals</td></tr><tr><td>1–20 — Novice</td><td>Basic actions and the core loop are usable without extreme failure RNG</td></tr><tr><td>20–40 — Competent</td><td>Reliable basics, more information and broader basic options</td></tr><tr><td>40–60 — Skilled</td><td>Useful in groups, supports a build, intermediate learned techniques/processes</td></tr><tr><td>60–80 — Professional</td><td>Character-defining skill, advanced situations and strong efficiency/consistency</td></tr><tr><td>80–90 — Expert</td><td>Difficult content/processes, advanced capability, strong interpretation and consistency</td></tr><tr><td>90–100 — Master</td><td>Top technical proficiency, very slow gains and separately learned advanced/master techniques; knowledge and reputation remain incomplete</td></tr></tbody></table><p>These are approximate bands, not exact unlock boundaries. Shared endpoints do not define competing checks. Low skill must work; higher investment remains valuable. Supporting skills and utility compete for the same cap as primary specializations.</p><h2 id="difficulty-envelope-and-readable-progression" tabindex="-1">Difficulty envelope and readable progression <a class="header-anchor" href="#difficulty-envelope-and-readable-progression" aria-label="Permalink to &quot;Difficulty envelope and readable progression&quot;">​</a></h2><p>Low skill should handle low-difficulty work consistently; high skill expands the comfortable, challenging and extreme envelope. Efficiency, quality, consistency and information can improve with skill. Skill 20 should not mean failing 80% of routine actions. No probability equation or universal task difficulty is selected.</p><p>Players should be able to understand “What do I gain from 50 to 70?” A possible presentation shows current capabilities, the next major capability and advanced/master capabilities, rather than only opaque per-point bonuses. Discovery stays separate: recipes, hidden techniques, world knowledge and secret interactions need not be revealed in advance. Explaining what a skill does is not exposing everything that exists.</p><h2 id="learning-skills-from-zero-and-teachers" tabindex="-1">Learning skills from zero and teachers <a class="header-anchor" href="#learning-skills-from-zero-and-teachers" aria-label="Permalink to &quot;Learning skills from zero and teachers&quot;">​</a></h2><p>At exactly 0, a character without starting fundamentals generally does not know how to begin. Learn them from a world source: NPC teacher, academy, guild, trainer or specialist. Basic instruction may raise skill to roughly <strong>5–10</strong> or otherwise unlock fundamentals; practice, exploration and use then continue development.</p><p>This keeps cities, institutions, NPCs and exploration relevant. It is a Proposed teaching direction, not a universal runtime gate already added to skill checks. Costs, availability, distribution and abuse prevention remain open. A <a href="/Syrolands-Public/game-design/characters/character-creation.html">starting competency</a> can grant known fundamentals and approximately 20 skill without that initial teacher gate.</p><h2 id="reconciliation-and-open-questions" tabindex="-1">Reconciliation and open questions <a class="header-anchor" href="#reconciliation-and-open-questions" aria-label="Permalink to &quot;Reconciliation and open questions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Boundary / unresolved decision</th></tr></thead><tbody><tr><td>Exact skill budget</td><td>Approximately 700 is direction; final cap, allocation and locks are unresolved</td></tr><tr><td>Roster and metadata</td><td>Existing <a href="/Syrolands-Public/game-design/skills-and-knowledge.html">role documentation</a> is not an exhaustive roster. Static server metadata still includes Bowcraft/Fletching; <a href="/Syrolands-Public/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> remains a Proposed technique path. No removal, renumbering or conversion is performed</td></tr><tr><td>Magic</td><td><a href="/Syrolands-Public/game-design/magic.html#use-based-gain-and-structured-teaching">Magic training</a> has illustrative +5 training blocks and 55–60 first-day targets. They are not a general gain formula. Consistent routine tasks need reconciliation with spell attempt floors and fallible extreme Difficulty; magic is not silently rewritten</td></tr><tr><td>Batch 01</td><td>The 80–90 wording changes to Very slow in the latest proposal; all craft-specific production/discovery rules remain in <a href="/Syrolands-Public/game-design/professions/profession-system.html">Profession System</a></td></tr><tr><td>Combat skills</td><td>Review mandatory-status pressure on Anatomy, Tactics and Healing later. The approved Stage 2A Anatomy rule and combat formulas remain untouched</td></tr><tr><td>Inherited server</td><td>Existing gain/caps, creation validation and 120-cap mechanisms are compatibility gaps rather than decisions to retain or remove them</td></tr></tbody></table><p>Other open questions: exact gain timing; anti-macro/diminishing returns; skills with exceptional progression models; teacher costs, availability and abuse; respec/forgetting; legacy-character conversion if production characters matter; UI for current/next capability. No formula or implementation is invented to settle these questions.</p><h2 id="magic-knowledge-and-practice-—-batch-04" tabindex="-1">Magic knowledge and practice — Batch 04 <a class="header-anchor" href="#magic-knowledge-and-practice-—-batch-04" aria-label="Permalink to &quot;Magic knowledge and practice — Batch 04&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/magic/spell-knowledge.html">Core Patterns</a> separate learned knowledge from Magery execution. <a href="/Syrolands-Public/game-design/magic/memory-and-familiarity.html">Familiarity</a> is per-pattern practice outside skillcap, not a new capped skill. Magery 100 remains technical mastery under the Proposed no-ordinary-120 direction; rare knowledge, schools, variants, preparation and Inscription extend progression. Existing pacing/difficulty reconciliation above remains open.</p>',23)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
